+            .append(transformId)
+            .append(",frequency=")
+            .append(frequency)
+            .append(",lastTriggeredTimeMillis=")
+            .append(lastTriggeredTimeMillis)
+            .append(",failureCount=")
+            .append(failureCount)
+            .append(",nextScheduledTimeMillis=")
+            .append(nextScheduledTimeMillis)
+            .append(",listener=")
+            .append(listener)
+            .append("]")
+            .toString();
+    }
+}
